import './style.css';
import { cva, type VariantProps } from 'class-variance-authority';
import { Slot } from 'radix-ui';
import { cn } from '@/lib/utils';
import { Spinner } from '@/components/ui/spinner';

/*
 * @author: @joao-carmassi
 * @description: Enhanced button component with multiple variants, sizes, visual effects, icon support, and loading state
 * @version: 2.1.0
 * @date: 2026-22-02
 * @license: MIT
 * @website: https://joao-carmassi.github.io/enhanced-button-v4/
 * @github: https://github.com/joao-carmassi/enhanced-button-v4
 */

interface IconProps {
  icon: React.ComponentType<Record<string, never>>;
  iconPlacement: 'left' | 'right';
}

interface IconRefProps {
  icon?: never;
  iconPlacement?: undefined;
}

export interface ButtonProps
  extends
    React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof buttonVariants> {
  asChild?: boolean;
}

export type ButtonIconProps = IconProps | IconRefProps;

const buttonVariants = cva(
  "group/button inline-flex shrink-0 items-center justify-center gap-2 rounded-4xl border border-transparent bg-clip-padding text-sm font-medium whitespace-nowrap transition-all outline-none select-none focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/30 active:translate-y-px disabled:pointer-events-none disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-3 aria-invalid:ring-destructive/20 dark:aria-invalid:border-destructive/50 dark:aria-invalid:ring-destructive/40 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
  {
    variants: {
      variant: {
        default:
          'bg-primary text-primary-foreground hover:bg-primary/80 hover:ring-primary/90',
        destructive:
          'border-none bg-destructive/10 text-destructive hover:bg-destructive/20 focus-visible:border-destructive/40 focus-visible:ring-destructive/20 dark:bg-destructive/20 dark:hover:bg-destructive/30 dark:focus-visible:ring-destructive/40 hover:ring-destructive/40',
        outline:
          'border-border bg-background hover:bg-muted hover:text-foreground aria-expanded:bg-muted aria-expanded:text-foreground dark:bg-transparent dark:hover:bg-input/30 hover:ring-muted',
        secondary:
          'bg-secondary text-secondary-foreground hover:bg-secondary/80 aria-expanded:bg-secondary aria-expanded:text-secondary-foreground hover:ring-secondary/90',
        ghost:
          'hover:bg-muted hover:text-foreground aria-expanded:bg-muted aria-expanded:text-foreground dark:hover:bg-muted/50 hover:ring-accent/90',
        link: 'text-primary underline-offset-4 hover:underline hover:ring-primary/90',
      },
      effect: {
        expandIcon: 'group gap-0 relative',
        ringHover:
          'transition-all duration-300 hover:ring-2 hover:ring-offset-2 ring-offset-background',
        shine:
          'before:animate-shine-effect relative overflow-hidden before:absolute before:inset-0 before:rounded-[inherit] before:bg-[linear-gradient(45deg,transparent_25%,rgba(255,255,255,0.5)_50%,transparent_75%,transparent_100%)] before:bg-[length:250%_250%,100%_100%] before:bg-no-repeat',
        shineHover:
          'relative overflow-hidden before:absolute before:inset-0 before:rounded-[inherit] before:bg-[linear-gradient(45deg,transparent_25%,rgba(255,255,255,0.5)_50%,transparent_75%,transparent_100%)] before:bg-[length:250%_250%,100%_100%] before:bg-[position:200%_0,0_0] before:bg-no-repeat before:transition-[background-position_0s_ease] hover:before:bg-[position:-100%_0,0_0] before:duration-1000',
        gooeyRight:
          'relative z-0 overflow-hidden duration-500 before:absolute before:inset-0 before:-z-10 before:translate-x-[150%] before:translate-y-[150%] before:scale-[2.5] before:rounded-[100%] before:bg-gradient-to-r before:from-white/40 before:transition-transform before:duration-1000  hover:before:translate-x-[0%] hover:before:translate-y-[0%]',
        gooeyLeft:
          'relative z-0 overflow-hidden duration-500 after:absolute after:inset-0 after:-z-10 after:translate-x-[-150%] after:translate-y-[150%] after:scale-[2.5] after:rounded-[100%] after:bg-gradient-to-l after:from-white/40 after:transition-transform after:duration-1000  hover:after:translate-x-[0%] hover:after:translate-y-[0%]',
        underline:
          'relative !no-underline after:absolute after:bg-primary after:bottom-1.5 after:h-[1px] after:w-2/3 after:origin-bottom-left after:scale-x-100 hover:after:origin-bottom-right hover:after:scale-x-0 after:transition-transform after:ease-in-out after:duration-300',
        hoverUnderline:
          'relative !no-underline after:absolute after:bg-primary after:bottom-1.5 after:h-[1px] after:w-2/3 after:origin-bottom-right after:scale-x-0 hover:after:origin-bottom-left hover:after:scale-x-100 after:transition-transform after:ease-in-out after:duration-300',
        pulsating: 'animate-pulsating-effect',
        rainbow:
          'relative animate-rainbow-effect hover:brightness-110 hover:text-card border-0 bg-[linear-gradient(#121213,#121213),linear-gradient(#121213_50%,rgba(18,18,19,0.6)_80%,rgba(18,18,19,0)),linear-gradient(90deg,oklch(66.2%_0.225_25.9)_0%,oklch(90.7%_0.231_133)_20%,oklch(69.6%_0.165_251)_40%,oklch(80.2%_0.134_225)_60%,oklch(60.4%_0.26_302)_80%,oklch(66.2%_0.225_25.9)_100%)] bg-[length:200%] text-primary-foreground ![background-clip:padding-box,border-box,border-box] [background-origin:border-box] [border:calc(0.125rem)_solid_transparent] before:absolute before:bottom-[-20%] before:left-1/2 before:z-0 before:h-1/5 before:w-3/5 before:-translate-x-1/2 before:animate-rainbow before:bg-[linear-gradient(90deg,oklch(66.2%_0.225_25.9)_0%,oklch(90.7%_0.231_133)_20%,oklch(69.6%_0.165_251)_40%,oklch(80.2%_0.134_225)_60%,oklch(60.4%_0.26_302)_80%,oklch(66.2%_0.225_25.9)_100%)] before:[filter:blur(0.75rem)] dark:bg-[linear-gradient(#fff,#fff),linear-gradient(#fff_50%,rgba(255,255,255,0.6)_80%,rgba(0,0,0,0)),linear-gradient(90deg,oklch(66.2%_0.225_25.9)_0%,oklch(90.7%_0.231_133)_20%,oklch(69.6%_0.165_251)_40%,oklch(80.2%_0.134_225)_60%,oklch(60.4%_0.26_302)_80%,oklch(66.2%_0.225_25.9)_100%)]',
      },
      size: {
        default:
          'h-9 gap-1.5 px-3 has-data-[icon=inline-end]:pr-2.5 has-data-[icon=inline-start]:pl-2.5',
        xs: "h-6 gap-1 px-2.5 text-xs has-data-[icon=inline-end]:pr-2 has-data-[icon=inline-start]:pl-2 [&_svg:not([class*='size-'])]:size-3",
        sm: 'h-8 gap-1 px-3 has-data-[icon=inline-end]:pr-2 has-data-[icon=inline-start]:pl-2',
        lg: 'h-10 gap-1.5 px-4 has-data-[icon=inline-end]:pr-3 has-data-[icon=inline-start]:pl-3',
        icon: 'size-9',
        'icon-xs': "size-6 [&_svg:not([class*='size-'])]:size-3",
        'icon-sm': 'size-8',
        'icon-lg': 'size-10',
      },
    },
    defaultVariants: {
      variant: 'default',
      size: 'default',
    },
  },
);

function Button({
  className,
  variant = 'default',
  size = 'default',
  effect,
  icon: Icon,
  iconPlacement,
  asChild = false,
  loading = false,
  ...props
}: React.ComponentProps<'button'> &
  VariantProps<typeof buttonVariants> &
  ButtonIconProps & {
    asChild?: boolean;
    loading?: boolean;
  }) {
  const Comp = asChild ? Slot.Root : 'button';
  const isIconSize = size?.startsWith('icon');

  return (
    <Comp
      data-slot='button'
      data-variant={variant}
      data-size={size}
      className={cn(
        buttonVariants({ variant, effect, size, className }),
        effect === 'expandIcon' && (loading ? 'gap-2' : 'gap-0'),
      )}
      disabled={loading || props.disabled}
      {...props}
    >
      {!loading &&
        Icon &&
        iconPlacement === 'left' &&
        (effect === 'expandIcon' ? (
          <div className='w-0 overflow-hidden translate-x-[0%] pr-0 opacity-0 transition-all duration-200 group-hover:w-6 group-hover:translate-x-0 group-hover:pr-2 group-hover:opacity-100'>
            <Icon />
          </div>
        ) : (
          <Icon />
        ))}
      {!(loading && isIconSize) && (
        <Slot.Slottable>{props.children}</Slot.Slottable>
      )}
      {loading && <Spinner />}
      {!loading &&
        Icon &&
        iconPlacement === 'right' &&
        (effect === 'expandIcon' ? (
          <div className='w-0 overflow-hidden translate-x-full pl-0 opacity-0 transition-all duration-200 group-hover:w-5 group-hover:translate-x-0 group-hover:pl-1.5 group-hover:opacity-100'>
            <Icon />
          </div>
        ) : (
          <Icon />
        ))}
    </Comp>
  );
}

export { Button, buttonVariants };

[data-variant='default'] {
  --pulse-color: var(--primary);
}
[data-variant='destructive'] {
  --pulse-color: var(--destructive);
}
[data-variant='secondary'] {
  --pulse-color: var(--secondary-foreground);
}
[data-variant='outline'] {
  --pulse-color: var(--ring);
}
[data-variant='ghost'] {
  --pulse-color: var(--ring);
}

.before\:animate-shine-effect::before {
  animation: shine-effect 3s ease-out infinite;
}

.animate-rainbow-effect {
  animation: rainbow-effect 3s linear infinite;
}

.animate-pulsating-effect {
  animation: pulsating-effect 1.5s ease-out infinite;
}

.card-shine-effect {
  animation: card-shine-effect var(--duration) infinite linear;
}

@keyframes shine-effect {
  0% {
    background-position: 200% 0;
  }
  25% {
    background-position: -200% 0;
  }
  100% {
    background-position: -200% 0;
  }
}

@keyframes rainbow-effect {
  0% {
    background-position: 0%;
  }
  100% {
    background-position: 200%;
  }
}

@keyframes pulsating-effect {
  0% {
    box-shadow: 0 0 0 0 var(--pulse-color, currentColor);
  }
  70% {
    box-shadow: 0 0 0 8px transparent;
  }
  100% {
    box-shadow: 0 0 0 0 transparent;
  }
}

@keyframes card-shine-effect {
  0% {
    background-position: 0% 0%;
  }
  50% {
    background-position: 100% 100%;
  }
  to {
    background-position: 0% 0%;
  }
}

/* ─── Aura Beam ─────────────────────────────────────────────────────────── */

@property --aura-angle {
  syntax: '<angle>';
  initial-value: 0deg;
  inherits: false;
}

@keyframes aura-spin {
  to {
    --aura-angle: 360deg;
  }
}

.aura-beam {
  --aura-padding: 2px;
  --aura-radius: 0.75rem;
  --aura-duration: 6s;
  --aura-color: var(--primary);
  --aura-color-from: var(--aura-color);
  --aura-color-to: var(--aura-color);

  position: relative;
  display: inline-block;
  padding: var(--aura-padding);
  border-radius: calc(var(--aura-radius) + var(--aura-padding));
  color: var(--aura-color);

  background-image: conic-gradient(
    from var(--aura-angle),
    transparent 0deg,
    transparent 220deg,
    currentColor 280deg,
    currentColor 360deg
  );

  animation: aura-spin var(--aura-duration) linear infinite;
}

.aura-beam > * {
  position: relative;
  z-index: 2;
  border-radius: var(--aura-radius);
}

.aura-beam::before,
.aura-beam::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: inherit;
  pointer-events: none;
  z-index: 0;
}

.aura-beam::before {
  filter: blur(6px);
  opacity: 0.65;
}

.aura-beam::after {
  filter: blur(18px);
  opacity: 0.35;
}

/* ─── Beam variant ────────────────────────────────────────────────────────── */

.aura-beam[data-variant='beam'] {
  background-image: conic-gradient(
    from var(--aura-angle),
    transparent 0deg,
    transparent 275deg,
    var(--aura-color-from) 305deg,
    var(--aura-color-to) 325deg,
    transparent 360deg
  );
}

.aura-beam[data-variant='beam']::before {
  filter: blur(4px);
  opacity: 0.85;
}

.aura-beam[data-variant='beam']::after {
  filter: blur(22px);
  opacity: 0.55;
}

/* ─── Shine variant ───────────────────────────────────────────────────────── */

@keyframes aura-shine {
  0% {
    background-position: 00% 00%;
  }
  50% {
    background-position: 100% 100%;
  }
  100% {
    background-position: 00% 00%;
  }
}

.aura-beam[data-variant='shine'] {
  background-image: radial-gradient(
    transparent,
    transparent,
    var(--aura-color),
    transparent,
    transparent
  );
  background-size: 300% 300%;
  animation: aura-shine var(--aura-duration) ease-in-out infinite;
}

.aura-beam[data-variant='shine']::before {
  filter: blur(8px);
  opacity: 0.7;
  animation: aura-shine var(--aura-duration) ease-in-out infinite;
}

.aura-beam[data-variant='shine']::after {
  filter: blur(26px);
  opacity: 0.42;
  animation: aura-shine var(--aura-duration) ease-in-out infinite;
}

/* ─── Glow variant (cursor proximity) ─────────────────────────────────────── */

@property --aura-glow-opacity {
  syntax: '<number>';
  initial-value: 0;
  inherits: true;
}

.aura-beam[data-variant='glow'] {
  --aura-x: 50%;
  --aura-y: 0px;
  --aura-cone: 140px;
  --aura-color-third: var(--aura-color-to);

  animation: none;
  transition: --aura-glow-opacity 0.18s ease;
  background-origin: border-box;

  background-image: radial-gradient(
    circle var(--aura-cone) at var(--aura-x) var(--aura-y),
    color-mix(
        in srgb,
        var(--aura-color-from) calc(var(--aura-glow-opacity) * 100%),
        transparent
      )
      0%,
    color-mix(
        in srgb,
        var(--aura-color-to) calc(var(--aura-glow-opacity) * 78%),
        transparent
      )
      45%,
    color-mix(
        in srgb,
        var(--aura-color-third) calc(var(--aura-glow-opacity) * 50%),
        transparent
      )
      75%,
    transparent 100%
  );
}

.aura-beam[data-variant='glow']::before {
  filter: blur(5px);
  opacity: 0.85;
}

.aura-beam[data-variant='glow']::after {
  filter: blur(24px);
  opacity: 0.5;
}
